function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 1000) return 'grid needs 2 to 1000 rows.';
  const n = grid[0].length;
  if (n < 2 || n > 1000) return 'grid needs 2 to 1000 columns.';
  if (grid.length * n > 100000) return 'grid can hold at most 10^5 cells.';
  for (const line of grid) {
    if (!Array.isArray(line) || line.length !== n) return 'Every row must have the same length.';
    for (const v of line) if (!Number.isInteger(v) || v < 1 || v > 1000000) return 'Each value is an integer from 1 to 10^6.';
  }
  return null;
}

