function maxMoves(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const dp = Array.from({ length: rows }, () => new Array(cols).fill(0));

  for (let col = cols - 2; col >= 0; col--) {
    for (let row = 0; row < rows; row++) {
      for (let next = row - 1; next <= row + 1; next++) {
        if (next < 0 || next >= rows) {
          continue;
        }
        if (grid[next][col + 1] > grid[row][col]) {
          dp[row][col] = Math.max(dp[row][col], dp[next][col + 1] + 1);
        }
      }
    }
  }

  let best = 0;
  for (let row = 0; row < rows; row++) {
    best = Math.max(best, dp[row][0]);
  }
  return best;
}

