function maxMoves(grid) {
  const m = grid.length, n = grid[0].length;
  const walk = (r, c) => {
    let most = 0;
    if (c + 1 >= n) return 0;
    for (const d of [-1, 0, 1]) {
      const nr = r + d;
      if (nr >= 0 && nr < m && grid[nr][c + 1] > grid[r][c]) most = Math.max(most, 1 + walk(nr, c + 1));
    }
    return most;
  };
  let answer = 0;
  for (let r = 0; r < m; r++) answer = Math.max(answer, walk(r, 0));
  return answer;
}

