function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n;
  if (size === 'large') {
    const shapes = [[100, 100], [50, 100], [100, 50], [20, 100]];
    [m, n] = shapes[Math.floor(rand() * shapes.length)];
  } else {
    m = pick(2, 6);
    n = pick(2, 7);
  }
  const style = Math.floor(rand() * 3);
  const step = size === 'large' ? pick(1, 200) : pick(1, 4);
  const noise = size === 'large' ? pick(1, 400) : pick(1, 8);
  const grid = [];
  for (let r = 0; r < m; r++) {
    const line = [];
    for (let c = 0; c < n; c++) {
      let v;
      if (style === 0) v = pick(1, size === 'large' ? 1000000 : 6);
      else if (style === 1) v = 1 + c * step + Math.floor(rand() * noise);
      else v = rand() < 0.1 ? 1000000 : 1 + c * step + Math.floor(rand() * noise);
      line.push(Math.min(v, 1000000));
    }
    grid.push(line);
  }
  return [grid];
}
